css_custom_properties:
:root {
  /* ============================================
     HAIR ARTISTS — DESIGN SYSTEM v1.0
     2026-06-03 | style: modern-luxe-accessible
     Fonts: Plus Jakarta Sans + Lato (Google Fonts)
  ============================================ */

  /* --- COULEURS PRINCIPALES --- */
  --color-primary:            #0D0D0D;
  --color-primary-hover:      #1A1A1A;
  --color-primary-light:      #2C2C2C;

  /* --- ACCENT OR — CTA, notes, étoiles --- */
  --color-accent:             #C9963A;
  --color-accent-hover:       #B8852E;
  --color-accent-light:       #F2E0BB;

  /* --- FONDS --- */
  --color-bg:                 #FFFFFF;
  --color-bg-alt:             #FAF8F6;
  --color-bg-dark:            #0D0D0D;
  --color-surface:            #FFFFFF;
  --color-surface-alt:        #F5F3F0;

  /* --- TEXTE --- */
  --color-text:               #0D0D0D;
  --color-text-secondary:     #3D3D3D;
  --color-text-muted:         #6B6B6B;
  --color-text-on-dark:       #FFFFFF;
  --color-text-on-dark-muted: #B8B8B8;
  --color-text-on-accent:     #0D0D0D;

  /* --- BORDURES --- */
  --color-border:             #E8E4DE;
  --color-border-strong:      #C9963A;

  /* --- ÉTATS SÉMANTIQUES --- */
  --color-success:            #2D7A3A;
  --color-success-light:      #EBF5EC;
  --color-error:              #C0392B;
  --color-warning:            #D97706;
  --color-star:               #C9963A;

  /* --- BADGES SPÉCIAUX --- */
  --color-badge-vegetal:      #2D7A3A;
  --color-badge-vegetal-bg:   #EBF5EC;
  --color-badge-medical:      #4A6FA5;
  --color-badge-medical-bg:   #EEF2F9;

  /* --- OVERLAYS --- */
  --overlay-dark:             rgba(13,13,13,0.72);
  --overlay-light:            rgba(13,13,13,0.45);

  /* ============================================
     TYPOGRAPHIE
  ============================================ */
  --font-heading: 'Plus Jakarta Sans', system-ui, sans-serif;
  --font-body:    'Lato', system-ui, sans-serif;

  /* Échelle fixe */
  --text-xs:   0.75rem;   /* 12px */
  --text-sm:   0.875rem;  /* 14px */
  --text-base: 1rem;      /* 16px */
  --text-lg:   1.125rem;  /* 18px */
  --text-xl:   1.25rem;   /* 20px */
  --text-2xl:  1.5rem;    /* 24px */
  --text-3xl:  1.875rem;  /* 30px */
  --text-4xl:  2.25rem;   /* 36px */
  --text-5xl:  3rem;      /* 48px */

  /* Échelle fluide */
  --text-hero: clamp(2.5rem, 6vw, 4.5rem);
  --text-h1:   clamp(2rem, 4.5vw, 3.5rem);
  --text-h2:   clamp(1.625rem, 3.5vw, 2.5rem);
  --text-h3:   clamp(1.25rem, 2.5vw, 1.75rem);
  --text-h4:   clamp(1.125rem, 2vw, 1.375rem);
  --text-price:clamp(1.5rem, 3vw, 2rem);

  /* Graisses */
  --weight-light:     300;
  --weight-regular:   400;
  --weight-medium:    500;
  --weight-semibold:  600;
  --weight-bold:      700;
  --weight-extrabold: 800;

  /* Interlignes */
  --leading-tight:   1.1;
  --leading-snug:    1.25;
  --leading-normal:  1.5;
  --leading-relaxed: 1.65;
  --leading-loose:   1.85;

  /* Espacement lettre */
  --tracking-tighter: -0.03em;
  --tracking-tight:   -0.02em;
  --tracking-snug:    -0.01em;
  --tracking-normal:   0;
  --tracking-wide:     0.02em;
  --tracking-wider:    0.04em;
  --tracking-widest:   0.06em;
  --tracking-label:    0.12em;

  /* ============================================
     ESPACEMENT — base 4px
  ============================================ */
  --space-1:   4px;
  --space-2:   8px;
  --space-3:  12px;
  --space-4:  16px;
  --space-5:  20px;
  --space-6:  24px;
  --space-8:  32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;
  --space-20: 80px;
  --space-24: 96px;
  --space-32: 128px;

  /* Espacement composants */
  --section-py:      clamp(64px, 8vw, 96px);
  --section-py-sm:   clamp(40px, 6vw, 64px);
  --container-max:   1200px;
  --container-px:    clamp(16px, 5vw, 32px);
  --grid-gap:        24px;
  --grid-gap-lg:     32px;
  --card-padding:    clamp(20px, 4vw, 32px);
  --nav-height:      72px;
  --nav-height-mob:  64px;
  --hero-min-h:      clamp(560px, 80vh, 800px);

  /* ============================================
     BORDER RADIUS
  ============================================ */
  --radius-xs:   2px;
  --radius-sm:   6px;
  --radius-md:  10px;
  --radius-lg:  14px;
  --radius-xl:  20px;
  --radius-2xl: 28px;
  --radius-full: 9999px;

  /* Tokens sémantiques */
  --radius-card:   14px;
  --radius-button: 9999px;
  --radius-badge:  9999px;
  --radius-input:  8px;
  --radius-icon:   12px;
  --radius-img:    10px;

  /* ============================================
     OMBRES
  ============================================ */
  --shadow-xs:          0 1px 3px rgba(13,13,13,0.06), 0 1px 2px rgba(13,13,13,0.04);
  --shadow-sm:          0 2px 8px rgba(13,13,13,0.08), 0 1px 3px rgba(13,13,13,0.05);
  --shadow-md:          0 4px 16px rgba(13,13,13,0.10), 0 2px 6px rgba(13,13,13,0.06);
  --shadow-lg:          0 8px 28px rgba(13,13,13,0.12), 0 4px 10px rgba(13,13,13,0.07);
  --shadow-xl:          0 16px 48px rgba(13,13,13,0.14), 0 6px 16px rgba(13,13,13,0.08);
  --shadow-2xl:         0 24px 64px rgba(13,13,13,0.18);
  --shadow-accent:      0 4px 20px rgba(201,150,58,0.30), 0 2px 8px rgba(201,150,58,0.15);
  --shadow-accent-h:    0 6px 28px rgba(201,150,58,0.40), 0 3px 10px rgba(201,150,58,0.20);
  --shadow-card-hover:  0 12px 36px rgba(13,13,13,0.14), 0 4px 12px rgba(13,13,13,0.08);
  --shadow-nav:         0 2px 16px rgba(13,13,13,0.15);

  /* ============================================
     ANIMATIONS & TRANSITIONS
  ============================================ */
  --ease:        cubic-bezier(0.4,0,0.2,1);
  --ease-spring: cubic-bezier(0.34,1.56,0.64,1);
  --ease-in:     cubic-bezier(0.4,0,1,1);
  --ease-out:    cubic-bezier(0,0,0.2,1);

  --dur-fast:   150ms;
  --dur-normal: 250ms;
  --dur-slow:   400ms;

  --t-fast:   150ms cubic-bezier(0.4,0,0.2,1);
  --t-normal: 250ms cubic-bezier(0.4,0,0.2,1);
  --t-slow:   400ms cubic-bezier(0.4,0,0.2,1);

  /* ============================================
     COMPOSANTS SÉMANTIQUES — BOUTONS
  ============================================ */

  /* CTA principal — or sur fond sombre */
  --btn-cta-bg:        #C9963A;
  --btn-cta-color:     #0D0D0D;
  --btn-cta-bg-hover:  #B8852E;
  --btn-cta-shadow:    0 4px 20px rgba(201,150,58,0.30);
  --btn-cta-shadow-h:  0 6px 28px rgba(201,150,58,0.40);
  --btn-cta-padding:   16px 32px;
  --btn-cta-min-h:     52px;

  /* Bouton secondaire sur fond clair */
  --btn-sec-bg:        transparent;
  --btn-sec-color:     #0D0D0D;
  --btn-sec-border:    2px solid #0D0D0D;
  --btn-sec-bg-h:      #0D0D0D;
  --btn-sec-color-h:   #FFFFFF;

  /* Bouton secondaire sur fond sombre */
  --btn-dark-bg:       transparent;
  --btn-dark-color:    #FFFFFF;
  --btn-dark-border:   2px solid rgba(255,255,255,0.50);
  --btn-dark-bg-h:     rgba(255,255,255,0.08);
  --btn-dark-border-h: 2px solid #FFFFFF;

  /* Bouton téléphone */
  --btn-phone-bg:      #0D0D0D;
  --btn-phone-color:   #FFFFFF;
  --btn-phone-bg-h:    #2C2C2C;
  --btn-phone-padding: 12px 24px;
  --btn-phone-min-h:   48px;

  /* ============================================
     FOCUS — ACCESSIBILITÉ
  ============================================ */
  --focus-ring:        0 0 0 3px rgba(201,150,58,0.40);
  --focus-offset:      2px;
  --min-touch:         44px;
  --min-touch-cta:     52px;
}
